import * as React from "react";
import { cn } from "cn";

import { Button } from "./button";
import { Icon } from "./icon";
import { Skeleton } from "./skeleton";
import { Spinner } from "./spinner";

import styles from "./settings-card.module.css";

type SaveState =
  | { kind: "idle" }
  | { kind: "saving" }
  | { kind: "saved" }
  | { kind: "failed"; message: string };

export type SettingsCardProps = Omit<
  React.ComponentPropsWithoutRef<"section">,
  "title" | "onSubmit"
> & {
  title: React.ReactNode;
  description?: React.ReactNode;
  action?: React.ReactNode;
  dirty?: boolean;
  onSave?: () => void | Promise<unknown>;
  onDiscard?: () => void;
  hint?: React.ReactNode;
  locked?: React.ReactNode;
  loading?: boolean;
  saveLabel?: string;
  tone?: "default" | "danger";
  actions?: React.ReactNode;
};

export const SettingsCard = React.forwardRef<HTMLElement, SettingsCardProps>(
  (
    {
      title,
      description,
      action,
      dirty = false,
      onSave,
      onDiscard,
      hint,
      locked,
      loading = false,
      saveLabel = "Save",
      tone = "default",
      actions,
      children,
      className,
      ...props
    },
    ref
  ) => {
    const [state, setState] = React.useState<SaveState>({ kind: "idle" });
    const titleId = React.useId();
    React.useEffect(() => {
      if (state.kind !== "saved") return undefined;
      const timer = window.setTimeout(() => setState({ kind: "idle" }), 3000);
      return () => window.clearTimeout(timer);
    }, [state.kind]);
    React.useEffect(() => {
      if (dirty && state.kind === "saved") setState({ kind: "idle" });
    }, [dirty, state.kind]);
    const saving = state.kind === "saving";
    const save = async () => {
      if (!onSave || !dirty || saving || locked) return;
      setState({ kind: "saving" });
      try {
        await onSave();
        setState({ kind: "saved" });
      } catch (error) {
        setState({
          kind: "failed",
          message: error instanceof Error ? error.message : "The change was not saved. Try again."
        });
      }
    };
    let status: React.ReactNode = hint;
    if (locked)
      status = (
        <>
          <Icon name="lock" size={14} />
          {locked}
        </>
      );
    else if (saving)
      status = (
        <>
          <Spinner />
          Saving
        </>
      );
    else if (state.kind === "failed")
      status = <span className={styles.failed}>{state.message}</span>;
    else if (state.kind === "saved")
      status = (
        <>
          <Icon name="check-c" size={14} className={styles.saved} />
          Saved
        </>
      );
    else if (dirty)
      status = (
        <>
          <span className={styles.dirtyMark} aria-hidden="true" />
          Unsaved changes
        </>
      );
    return (
      <section
        ref={ref}
        data-slot="settings-card"
        data-tone={tone}
        aria-labelledby={titleId}
        className={cn(styles.card, className)}
        {...props}
      >
        <form
          noValidate
          onSubmit={(event) => {
            event.preventDefault();
            save();
          }}
        >
          <div className={styles.header}>
            <div className={styles.copy}>
              <h3 id={titleId} className={styles.title}>
                {title}
              </h3>
              {description && <p className={styles.description}>{description}</p>}
            </div>
            {action && <div className={styles.action}>{action}</div>}
          </div>
          <fieldset className={styles.content} disabled={Boolean(locked) || saving}>
            {loading ? <Skeleton lines={2} height={32} /> : children}
          </fieldset>
          <div className={styles.footer}>
            <p className={styles.status} role="status">
              {status}
            </p>
            {!locked && (
              <div className={styles.buttons}>
                {tone === "danger" ? (
                  actions
                ) : (
                  <>
                    {dirty && onDiscard && !saving && (
                      <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        onClick={() => {
                          onDiscard();
                          setState({ kind: "idle" });
                        }}
                      >
                        Discard
                      </Button>
                    )}
                    {onSave && (
                      <Button
                        type="submit"
                        variant="primary"
                        size="sm"
                        disabled={!dirty || loading}
                        loading={saving}
                      >
                        {saveLabel}
                      </Button>
                    )}
                  </>
                )}
              </div>
            )}
          </div>
        </form>
      </section>
    );
  }
);
SettingsCard.displayName = "SettingsCard";

.card {
  min-width: 0;
  overflow: hidden;
  border: var(--v4-size-control-border) solid var(--v4-line);
  border-radius: calc(var(--v4-radius-card) * var(--corners));
  background: var(--v4-surface);
  color: var(--v4-ink);
}
.card[data-tone="danger"] {
  border-color: var(--v4-bad-line);
}
.header {
  display: flex;
  align-items: flex-start;
  gap: var(--v4-space-12);
  padding: var(--v4-space-surface-inset) var(--v4-space-surface-inset) 0;
}
.copy {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  gap: var(--v4-space-4);
  min-width: 0;
}
.title {
  margin: 0;
  font-family: var(--v4-type-title-sm-font-family);
  font-size: var(--v4-type-title-sm-font-size);
  line-height: var(--v4-type-title-sm-line-height);
  font-weight: var(--v4-type-title-sm-font-weight);
  letter-spacing: var(--v4-type-title-sm-letter-spacing);
}
.description {
  margin: 0;
  color: var(--v4-text2);
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.action {
  display: flex;
  flex: none;
  align-items: center;
  gap: var(--v4-space-8);
}
.content {
  display: flex;
  flex-direction: column;
  gap: var(--v4-space-field-group);
  min-width: 0;
  margin: 0;
  padding: var(--v4-space-16) var(--v4-space-surface-inset) var(--v4-space-surface-inset);
  border: 0;
}
.content > [data-slot="field"],
.content > [data-slot="input"] {
  max-width: 480px;
}
.footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--v4-space-12);
  min-height: calc(var(--v4-size-control-sm) + 2 * var(--v4-space-12));
  padding: var(--v4-space-12) var(--v4-space-12) var(--v4-space-12) var(--v4-space-surface-inset);
  border-top: 1px solid var(--v4-line-soft);
  background: var(--v4-paper);
}
.card[data-tone="danger"] .footer {
  border-top-color: var(--v4-bad-line);
  background: var(--v4-bad-wash);
}
.status {
  display: flex;
  align-items: center;
  gap: var(--v4-space-8);
  min-width: 0;
  margin: 0;
  color: var(--v4-text2);
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.dirtyMark {
  flex: none;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--v4-warn);
}
.saved {
  color: var(--v4-ok);
}
.failed {
  color: var(--v4-bad);
}
.buttons {
  display: flex;
  flex: none;
  align-items: center;
  gap: var(--v4-space-12);
}
